    x.strokeStyle = '#212529'; x.lineWidth = 1.5; x.beginPath(); for (let i = 0; i < 200; i++) { const v = S.img.d[3 * (row * 200 + i) + 2]; i ? x.lineTo(X(i), Y(v)) : x.moveTo(X(i), Y(v)); } x.stroke();
    x.strokeStyle = f < 0 ? '#e03131' : '#2f9e44'; x.lineWidth = 1; x.beginPath(); for (let i = 0; i < 200; i++) { const v = im.d[3 * (row * 200 + i) + 2]; i ? x.lineTo(X(i), Y(v)) : x.moveTo(X(i), Y(v)); } x.stroke();
