      const x = pc.getContext('2d'); x.clearRect(0, 0, 600, 210); const n = s.length, X = i => 30 + i / (n - 1) * 560;
      x.fillStyle = '#868e96'; x.font = '10px sans-serif'; x.fillText('בהירות', 540, 12); x.fillText('הפרש לשכן (נגזרת)', 500, 122);
      x.strokeStyle = '#212529'; x.lineWidth = 1.5; x.beginPath(); s.forEach((p, i) => { const y = 95 - p[2] / 255 * 85; i ? x.lineTo(X(i), y) : x.moveTo(X(i), y); }); x.stroke();
      const z = 165, sc = 40 / Math.max(thr * 1.4, ...d.map(Math.abs), 1); x.strokeStyle = '#ced4da'; x.lineWidth = 1; x.beginPath(); x.moveTo(30, z); x.lineTo(590, z); x.stroke(); x.fillStyle = 'rgba(250,176,5,.15)'; x.fillRect(30, z - thr * sc, 560, 2 * thr * sc);
      d.forEach((v, i) => { const xx = (X(i) + X(i + 1)) / 2; x.fillStyle = Math.abs(v) >= thr ? (v > 0 ? '#f08c00' : '#1971c2') : '#adb5bd'; x.fillRect(xx - 1.5, v > 0 ? z - v * sc : z, 3, Math.max(1, Math.abs(v) * sc)); });
      peaks.forEach(i => { x.strokeStyle = 'rgba(255,0,255,.35)'; x.setLineDash([3, 3]); x.beginPath(); x.moveTo((X(i) + X(i + 1)) / 2, 5); x.lineTo((X(i) + X(i + 1)) / 2, 205); x.stroke(); x.setLineDash([]); });
      out.innerHTML = 'לאורך הקו: <b>' + peaks.length + '</b> קצוות. כתום — עולים לבהיר (הפרש חיובי), כחול — יורדים לכהה (שלילי). ' + (peaks.length ? 'הגדול שבהם: ' + ltr(String(Math.max(...peaks.map(i => Math.abs(d[i]))))) + ' רמות בפיקסל אחד.' : 'הזז את הקו כך שיחצה את הכביש, את הכדור או את החוט.') + ' שים לב: באזור אחיד ההפרשים קרובים ל־0 — גם כשהבהירות עצמה גבוהה.';
