    const k = m === 2 ? 6 : 8, AtA = [...Array(k)].map(() => new Array(k).fill(0)), Atb = new Array(k).fill(0); const add = (row, val) => { for (let i = 0; i < k; i++) { Atb[i] += row[i] * val; for (let j = 0; j < k; j++) AtA[i][j] += row[i] * row[j]; } };
