  const cv = canvasPx(flex(box), 640, 240, 640); const out = V.say(box);
  function reset() { clearInterval(timer); it = 0; best = null; last = null; r = IM.rng(11); const good = P.M.filter(m => m.d1 < 0.75 * m.d2); src = good.map(m => [P.K1[m.i].x, P.K1[m.i].y]); dst = good.map(m => [P.K2[m.j].x, P.K2[m.j].y]); right = good.map(m => isRight(P, m));
    const rr = IM.rng(5); for (let i = 0; i < extra; i++) { src.push([rr() * 320, rr() * 240]); dst.push([rr() * 320, rr() * 240]); right.push(false); } draw(); }
  function one() { const n = src.length, idx = new Set(); while (idx.size < 4) idx.add(Math.floor(r() * n)); const I = [...idx]; const H = persp(I.map(i => src[i]), I.map(i => dst[i])); it++; if (!H) return;
    const inl = []; for (let i = 0; i < n; i++) { const p = apply3(H, src[i][0], src[i][1]); if (p[4] > 0 && Math.hypot(p[0] - dst[i][0], p[1] - dst[i][1]) < 3) inl.push(i); } last = { I, H, inl }; if (!best || inl.length > best.inl.length) best = { I, H, inl, at: it }; draw(); }
