/* ===================================================== chapter 10: optical flow ===================================================== */
/* float gray helpers. Images: { w, h, d: Float32Array } */
const rf = (n, w) => { if (n < 0) n = -n - 1; if (n >= w) n = 2 * w - n - 1; return clamp(n, 0, w - 1); };           // BORDER_REFLECT
function bil(g, x, y) { const w = g.w, h = g.h, x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0; const a = g.d[rf(y0, h) * w + rf(x0, w)], b = g.d[rf(y0, h) * w + rf(x0 + 1, w)], c = g.d[rf(y0 + 1, h) * w + rf(x0, w)], d = g.d[rf(y0 + 1, h) * w + rf(x0 + 1, w)]; return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy; }
