function pyrLK(PA, PB, pts, r, L, iters, me0) { return pts.map(([x, y]) => { let gu = 0, gv = 0, ok = true; const trace = [];
  for (let l = L; l >= 0; l--) { const s = 2 ** l; const [u, v, st] = lkLevel(PA[l], PB[l], x / s, y / s, gu, gv, r, iters || 20, me0); if (!st) ok = false; trace.push([l, u * s, v * s]); if (l) { gu = 2 * u; gv = 2 * v; } else { gu = u; gv = v; } }
  const nx = x + gu, ny = y + gv; if (nx < 0 || ny < 0 || nx > PA[0].g.w - 1 || ny > PA[0].g.h - 1) ok = false; return { x, y, u: gu, v: gv, ok, trace }; }); }
const med = a => { const s = a.slice().sort((p, q) => p - q); return s.length ? (s.length % 2 ? s[s.length >> 1] : (s[s.length / 2 - 1] + s[s.length / 2]) / 2) : NaN; };
/* the chapter's frames: the drone scene in gray, no noise, plus (optionally) a car that drives on its own */
function base10() { return CACHE.b10 || (CACHE.b10 = rnd(IM.toGray(droneScene({ shadow: 1, noise: 0, seed: 3, road: '#3a3a3a' }).img))); }
function carOn(g, cx, cy) { const o = IM.copy(g); for (let y = 0; y < o.h; y++) for (let x = 0; x < o.w; x++) { const X = x - cx, Y = y - cy; if (Math.abs(X) <= 10 && Math.abs(Y) <= 5) o.d[y * o.w + x] = Math.abs(X) <= 3 && Math.abs(Y) <= 3 ? 35 : X > 6 ? 205 : 150; } return o; }
function frames10(dx, dy, car) { const g = base10(); let a = g, b = shiftG(g, dx, dy); if (car) { a = carOn(a, 60, 96); b = carOn(b, 60 + car[0], 96 + car[1]); } return [a, b]; }
