      if (!p.ok) { ctx.fillStyle = '#868e96'; ctx.fillRect(p.x - 0.5, p.y - 0.5, 1.5, 1.5); return; } ok++; us.push(p.u); vs.push(p.v); const good = Math.hypot(p.u - tu, p.v - tv) < 1; if (good) right++;
