function shakes11(o) { o = Object.assign({ sd: 1.8, asd: 0.6, seed: 7, pan: 0 }, o); const r = IM.rng(o.seed * 31 + 1); const S = []; for (let i = 0; i < NF; i++) S.push([IM.randn(r) * o.sd + o.pan * i, IM.randn(r) * o.sd, IM.randn(r) * o.asd]); return S; }
