  V.btns(box, [['▶ נגן / עצור', () => { if (timer) { clearInterval(timer); timer = null; } else timer = setInterval(() => { if (!document.body.contains(box)) return clearInterval(timer); i = (i + 1) % NF; show(); }, 70); }, 'primary']]);
