  let S; function draw() { S = shakes11({ sd, asd }); show(); }
  function show() { const W0 = IM.copy(world11()); const [bx, by] = ballAt(i); const ctx = IM.show(cw, W0); ctx.fillStyle = 'rgb(255,200,0)'; ctx.beginPath(); ctx.arc(bx, by, 7, 0, 7); ctx.fill();
    const Mi = inv23(camM(...S[i])); const Q = [[0, 0], [FW, 0], [FW, FH], [0, FH]].map(p => ap23(Mi, p[0], p[1])); ctx.strokeStyle = '#ffd43b'; ctx.lineWidth = 1.5; ctx.beginPath(); Q.forEach((p, k) => k ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath(); ctx.stroke();
    IM.show(cf, frame11(S, i)); const dxs = S.map(s => s[0]), dif = dxs.map((v, k) => k ? v - dxs[k - 1] : 0); lplot(cv, [{ y: dxs, color: '#1c7ed6' }, { y: dif, color: '#e8590c', lw: 1 }], [-20, 20], { marks: [{ i }], ylab: 'פיקסלים' });
    out.innerHTML = 'פריים ' + i + ': ' + ltr('dx = ' + F(S[i][0], 1) + ', dy = ' + F(S[i][1], 1) + ', angle = ' + F(S[i][2], 2) + '°') + '. סטיית התקן של הרעידה: <b>' + F(stdv(dxs), 2) + '</b>; של ההפרש בין פריימים: <b>' + F(stdv(dif.slice(1)), 2) + '</b> — פי ' + F(stdv(dif.slice(1)) / Math.max(1e-9, stdv(dxs)), 2) + '. ההפרש בין שתי רעידות בלתי תלויות גדול פי ' + ltr('√2 ≈ 1.41') + ' מכל אחת. בגלל זה בסעיף 11.5 נמדדת "רעידה" של 10 פיקסלים, אף שהסטייה שנבחרה היא 6.'; }
