  const sr = el('div', { class: 'row' }); box.appendChild(sr); V.slider(sr, 'radius', 0, 40, 1, rad, v => { rad = v; draw(); }); V.slider(sr, 'zoom', 1, 1.3, 0.02, zoom, v => { zoom = v; draw(); });
  V.tabs(box, ['רק רעידה', 'רעידה + פנייה איטית'], k => { pan = k; start(); }); const prog = el('div', { class: 'note-small', style: { textAlign: 'center' } }); box.appendChild(prog);
  const cv = canvasPx(box, 640, 220, 640); V.legend(box, [['#1c7ed6', 'רעידה שנשארה (סטיית תקן, x)'], ['#e8590c', 'תיקון מקסימלי (פיקסלים)'], ['#868e96', 'מה שהזום מסתיר']]); const tb = el('div'); box.appendChild(tb); const out = V.say(box);
  function start() { S = shakes11({ pan: pan ? 0.25 : 0 }); mot = null; measure11('p' + pan, S, f => { prog.textContent = 'מודד תנועות… ' + Math.round(f * 100) + '%'; }, m => { mot = m; prog.textContent = ''; draw(); }); }
  const stats = r => { const tr = cumsum(mot), sm = smoothPath(tr, r), corr = sm.map((s, k) => s.map((v, c) => v - tr[k][c])); const d = c => sm.slice(1).map((p, k) => p[c] - sm[k][c]);
    return { jx: stdv(d(0)), jy: stdv(d(1)), ja: stdv(d(2)) * 180 / Math.PI, mx: Math.max(...corr.map(c => Math.max(Math.abs(c[0]), Math.abs(c[1])))), corr }; };
  function draw() { if (!mot) return; const all = [...Array(41)].map((_, r) => stats(r)); const hide = (zoom - 1) / 2 * FH / zoom;
    const x = cv.getContext('2d'), Wd = 640, H = 220; x.clearRect(0, 0, Wd, H); const X = r => 40 + r / 40 * (Wd - 60), Y = v => H - 20 - v / 25 * (H - 34);
    x.strokeStyle = '#dee2e6'; x.beginPath(); x.moveTo(40, Y(0)); x.lineTo(Wd - 20, Y(0)); x.stroke(); x.fillStyle = '#868e96'; x.font = '10px sans-serif'; [0, 5, 10, 15, 20, 25].forEach(v => x.fillText(String(v), 20, Y(v) + 3)); [0, 10, 20, 30, 40].forEach(r => x.fillText(String(r), X(r) - 4, H - 6)); x.fillText('radius →', Wd - 70, H - 6);
    x.strokeStyle = '#868e96'; x.setLineDash([4, 3]); x.beginPath(); x.moveTo(40, Y(hide)); x.lineTo(Wd - 20, Y(hide)); x.stroke(); x.setLineDash([]);
    [['jx', '#1c7ed6'], ['mx', '#e8590c']].forEach(([k, col]) => { x.strokeStyle = col; x.lineWidth = 2.2; x.beginPath(); all.forEach((s, r) => r ? x.lineTo(X(r), Y(Math.min(25, s[k]))) : x.moveTo(X(r), Y(Math.min(25, s[k])))); x.stroke(); x.lineWidth = 1; });
    x.strokeStyle = '#212529'; x.beginPath(); x.moveTo(X(rad), 8); x.lineTo(X(rad), H - 20); x.stroke();
    const s0 = all[0], s = all[rad], bord = Math.max(...s.corr.map(c => borderFrac(mul23(zoomM(zoom), corrM(c)))));
    tb.innerHTML = table(['', 'רעידה x', 'רעידה y', 'רעידה בזווית (מעלות)', 'תיקון מקסימלי', 'שוליים שחורים'], [['לפני', F(s0.jx, 2), F(s0.jy, 2), F(s0.ja, 3), '—', '—'], ['radius = ' + rad, F(s.jx, 2), F(s.jy, 2), F(s.ja, 3), F(s.mx, 1), bord > 0.005 ? badge(false, Math.round(bord * 100) + '%') : badge(true, 'אין')]]);
    out.innerHTML = 'הרעידה ירדה פי <b>' + F(s0.jx / Math.max(1e-6, s.jx), 0) + '</b>. ' + (rad <= 4 ? 'רדיוס קטן: נשארות רעידות איטיות.' : bord > 0.005 ? 'התיקון גדול ממה שהזום מסתיר — יופיעו שוליים שחורים. הגדל את הזום (ותאבד שטח תמונה) או הקטן את הרדיוס.' : rad >= 30 ? 'הרעידה כמעט לא יורדת יותר, אבל התיקון ממשיך לגדול: אחרי נקודה מסוימת, רדיוס גדול יותר רק עולה בשטח תמונה.' : badge(true, 'איזון טוב') + ' — הרעידה נמוכה, והזום מסתיר את כל השוליים.') + ' (כאן הרעידה "אחרי" מחושבת מהמסלול המוחלק עצמו. הקוד של הסעיף מודד אותה מחדש על הסרטון המיוצב — ושם מתווספת גם שגיאת המדידה, ולכן יוצא שם 0.37 ולא אפס.)'; }
