/* ===================================================== chapter 12: the project ===================================================== */
/* the project video: the chapter 11 world plus a big orange-yellow tarp (the "big rectangle" of section 12.4); an orange ball, 1.5 px per frame */
function world12() { if (CACHE.w12) return CACHE.w12; const W0 = IM.copy(world11()); for (let y = 58; y < 80; y++) for (let x = 150; x < 184; x++) { const i = 3 * (y * WW + x); W0.d[i] = 20; W0.d[i + 1] = 190; W0.d[i + 2] = 250; } return (CACHE.w12 = W0); }
const BALL12 = [0, 140, 255], ball12 = i => [55 + 1.5 * i, 118], OPT12 = { world: null, col: BALL12, ballAt: ball12 };
const frame12 = (S, i, extra) => frame11(S, i, 6, Object.assign({}, OPT12, { world: world12() }, extra || {}));
const K12 = () => CACHE.k12 || (CACHE.k12 = kern('ellipse', 3));
/* find_ball of section 12.3 (scaled: min_area 25 instead of 200, 3x3 kernel instead of 5x5) */
function findBall12(im, lo, hi, morph, minA) { let m = IM.inRange(im, lo, hi, 'hsv'); if (morph !== false) m = CLS(OPN(m, K12()), K12()); const C = contours(m).filter(o => o.area > (minA || 25)); if (!C.length) return { p: null, C, m };
  const c = C.reduce((a, o) => o.area > a.area ? o : a); return { p: [c.cx, c.cy], c, C, m }; }
const jerk = path => { const p = path.filter(Boolean); if (p.length < 3) return NaN; let s = 0; for (let i = 2; i < p.length; i++) s += Math.hypot(p[i][0] - 2 * p[i - 1][0] + p[i - 2][0], p[i][1] - 2 * p[i - 1][1] + p[i - 2][1]); return s / (p.length - 2); };
const medSpeed = path => { const p = path.filter(Boolean), vx = [], vy = []; for (let i = 1; i < p.length; i++) { vx.push(p[i][0] - p[i - 1][0]); vy.push(p[i][1] - p[i - 1][1]); } return [med(vx), med(vy)]; };
