    const A = []; for (let t = 2; t < 80; t++) A.push(Math.hypot(P[t][0] - 2 * P[t - 1][0] + P[t - 2][0], P[t][1] - 2 * P[t - 1][1] + P[t - 2][1])); const J = A.reduce((s, v) => s + v, 0) / A.length;
